  :focus-visible { outline: 1.5px solid #dfedf9; outline-offset: 5px; }
}

/* THE CONSOLE MENU. Coordinates scale with the display, not with document flow. */
.console-environment {
  --anchor-x: 28.8vw;
  --category-y: 27vh;
  --selected-y: 47vh;
  --category-gap: 10.65vw;
  /* The top-right rail: the information icon and the clock share one fixed
     margin, so the corner reads identically on every screen. */
  --rail-right: 48px;
  --status-top: clamp(24px, 8vh, 72px);
  --status-width: clamp(340px, 33vw, 560px);
  --status-height: 76px;
  /* The console's own proportions: a selected category mark at ~5.3% of the
     width, a destination mark at ~5.7%, and its label at ~2.1%. Both axes
     count, so a short window keeps the same relationships. */
  --category-size: clamp(50px, min(6vw, 10vh), 132px);
  --item-size: clamp(56px, min(6.8vw, 11vh), 132px);
  --item-step-base: 8.2vh;
  --following-lead: 8vh;
  --label-gap: clamp(24px, 3.2vw, 80px);
  --menu-font: clamp(20px, min(2.05vw, 3.9vh), 36px);
  position: relative;
  isolation: isolate;
  width: 100%;
  height: 100dvh;
  overflow: hidden;
  background: #000;
}
.console-wallpaper-background { position: absolute; inset: 0; z-index: 0; pointer-events: none; background: radial-gradient(ellipse at 12% 10%, rgb(var(--wallpaper-light, 180 90 80) / 0.14), transparent 65%), linear-gradient(135deg, rgb(var(--wallpaper-top, 170 40 35)), rgb(var(--wallpaper-bottom, 100 15 22))); transition: filter 560ms ease; }
.console-wallpaper { position: absolute; inset: 0; z-index: 12; width: 100%; height: 100%; pointer-events: none; transition: filter 560ms cubic-bezier(0.16, 1, 0.3, 1); }
.console-wallpaper { -webkit-mask-image: linear-gradient(#000 0, #000 85%, transparent 98%); mask-image: linear-gradient(#000 0, #000 85%, transparent 98%); }
.wallpaper-canvas { position: absolute; inset: 0; width: 100%; height: 100%; transition: transform 560ms cubic-bezier(0.16, 1, 0.3, 1); }
/* System screens keep the shared silk field visible and in motion. */
.console-environment[data-surface="app"][data-notices="closed"] .console-wallpaper { filter: blur(3px) brightness(0.92); }
.console-environment[data-surface="app"][data-notices="closed"] .console-wallpaper-background { filter: brightness(0.94); }
.console-environment[data-surface="app"][data-notices="closed"] .wallpaper-canvas { transform: none; }
/* The menu owns the whole screen, so the fade belongs to it: the rows
   dissolve toward the footer, while the crossbar and every category stay in
   the fully opaque top. A zero-height <ul> would clip them instead — the
   mask must live on a box that really covers the column. */
.console-menu { position: absolute; inset: 0; z-index: 10; outline: none; transform-origin: 38% 43%; transition: opacity 360ms ease, transform 480ms ease, visibility 0s; -webkit-mask-image: linear-gradient(to bottom, #000 0, #000 78vh, transparent 92vh); mask-image: linear-gradient(to bottom, #000 0, #000 78vh, transparent 92vh); }
.console-menu[data-hidden="true"] { opacity: 0; visibility: hidden; pointer-events: none; transform: scale(1.13) translateX(-3vw); transition: opacity 280ms, transform 500ms, visibility 0s 400ms; }
/* Opening: the menu clears away while the selected icon grows and fades; Back plays it in reverse. */
.console-menu[data-opening="true"] { transform: scale(1.04) translateX(-0.6vw); }
.console-menu[data-opening="true"] .console-crossbar,
.console-menu[data-opening="true"] .console-selection-light,
.console-menu[data-opening="true"] .console-destination-position:not(.is-selected),
.console-menu[data-opening="true"] .console-destination-position.is-selected .console-item-label { opacity: 0; }
.console-menu[data-opening="true"] .console-description { animation: consoleFadeOut 200ms ease both; }
.console-menu[data-opening="true"] .console-destination-position.is-selected .console-item-art { transform: scale(2.1) translateX(20px); opacity: 0; transition: transform 260ms ease-out, opacity 260ms ease-in; }
.console-menu[data-returning="true"] .console-destination-position.is-selected .console-item-art { animation: consoleIconReturn 420ms cubic-bezier(0.2, 0.75, 0.25, 1) backwards; }
.console-menu[data-returning="true"] .console-destination-position.is-selected .console-item-label,
.console-menu[data-returning="true"] .console-description { animation: consoleFadeIn 360ms 120ms ease backwards; }
@keyframes consoleIconReturn { from { transform: scale(2.1) translateX(20px); opacity: 0; } }
@keyframes consoleFadeOut { to { opacity: 0; } }
@keyframes consoleFadeIn { from { opacity: 0; } }

.console-crossbar { position: absolute; top: var(--category-y); left: 0; width: 100%; height: calc(var(--category-size) * 1.35); transition: opacity 220ms ease; }
.console-category-track { display: flex; width: max-content; transform: translate3d(calc(var(--anchor-x) - var(--category-gap) / 2 - var(--selected-category) * var(--category-gap)), 0, 0); transition: transform 420ms cubic-bezier(0.2, 0.75, 0.25, 1); }
.console-category { position: relative; display: block; flex: 0 0 var(--category-gap); width: var(--category-gap); height: calc(var(--category-size) * 1.3); padding: 0; border: 0; background: transparent; color: #fff; outline-offset: 5px; }
.console-category-art { position: absolute; left: 50%; top: 0; display: block; width: var(--category-size); height: var(--category-size); transform: translate(-50%, -50%) scale(0.75); opacity: 0.5; transition: transform 330ms ease, opacity 300ms ease, filter 300ms ease; }
.console-category-art svg { width: 100%; height: 100%; }
.console-category.is-selected .console-category-art { opacity: 1; transform: translate(-50%, -50%) scale(1); filter: drop-shadow(0 0 5px #ffffff70); }
.console-category-label { position: absolute; top: calc(var(--category-size) * 0.65); left: 50%; transform: translateX(-50%); font: 400 clamp(14px, min(1.72vw, 2.9vh), 32px)/1.25 var(--font-sans); white-space: nowrap; opacity: 0; text-shadow: 0 1px 3px #0008; transition: opacity 240ms; }
.console-category.is-selected .console-category-label { opacity: 0.96; }

/* Reserve the crossbar's actual icon band, independently of the row step
   fitted above the footer. The nearest previous row ends above that band. */
.console-destinations { --previous-lift: max(0px, calc(var(--selected-y) - var(--category-y) + (var(--category-size) + var(--item-size)) / 2 + clamp(10px, 1.5vh, 24px) - var(--item-step))); position: absolute; top: var(--selected-y); left: var(--anchor-x); width: calc(100% - var(--anchor-x)); height: calc(100% - var(--selected-y)); }
/* The rows are absolutely positioned, so this <ul> has zero height: a
   mask-image on it would be measured against an empty box and clip the whole
   column (that was the regression). The fade lives on .console-menu, which
   really covers the screen, and keeps the footer line clear. */
.console-destinations ul { list-style: none; padding: 0; margin: 0; }
/* Size and opacity ride on --item-scale, set per row from the distance to
   the selection: the hardware interpolates continuously, not in two sizes. */
.console-destination-position { position: absolute; left: calc(var(--item-size) / -2); top: calc(var(--item-size) / -2); height: var(--item-size); width: calc(100vw - var(--anchor-x) - 4vw); transform: translate3d(0, calc(var(--item-offset) * var(--item-step) - var(--item-lift, 0px) + var(--item-lead, 0px)), 0); transition: transform 350ms cubic-bezier(0.22, 0.75, 0.25, 1), opacity 280ms ease; }
.console-destination-position.is-selected { z-index: 3; }
.console-destination { position: relative; display: flex; align-items: center; gap: var(--label-gap); width: fit-content; max-width: 100%; height: 100%; text-decoration: none; color: #f5f8ff; }
.console-item-art { flex: 0 0 var(--item-size); width: var(--item-size); height: var(--item-size); transform: scale(calc(var(--item-scale, 0.6) * 0.58)); transition: transform 300ms ease, opacity 200ms ease, filter 300ms ease; }
.console-item-art svg { display: block; width: 100%; height: 100%; }
.console-destination-position.is-selected .console-item-art { transform: scale(1); filter: drop-shadow(0 0 4px #ffffffa0) drop-shadow(0 0 10px #ffffff35); }
.console-item-label { font-size: max(calc(var(--menu-font) * var(--item-scale, 1)), 13px); font-weight: 400; line-height: 1.3; white-space: nowrap; text-shadow: none; transition: opacity 200ms ease; }
.console-destination-position.is-selected .console-item-label { text-shadow: 0 0 2px #ffffffc0, 0 0 6px #ffffff80, 0 0 13px #ffffff45; }
.console-item-subtitle { display: block; font-size: max(10px, calc(var(--menu-font) * var(--item-scale, 1) * 0.55)); line-height: 1.2; opacity: 0.45; white-space: nowrap; }
.console-destination:hover .console-item-label { color: #fff; }
.console-destination { color: #fff; }
.console-category-label { text-shadow: none; }
.console-notice-rail-icon { filter: drop-shadow(0 0 6px #ffffff70); }
.xmb-list-icon { filter: none; }
.xmb-list-row.is-selected .xmb-list-icon { filter: drop-shadow(0 0 4px #ffffff60); }
.console-external { display: inline-block; margin-left: 12px; font-size: 0.65em; opacity: 0.7; }
/* The destination stands in a column: the label, with the description
   beneath it — smaller, the same white, and the same shadow as the menu's
   own text. No box, no veil: white on the darkest of the twelve monthly
   palettes still clears 4.5:1, and the shadow carries the crossings of a
   bright ribbon. The block stays on one line, capped at 380px. */
.console-destination-body { display: flex; flex-direction: column; justify-content: center; gap: 3px; min-width: 0; max-width: min(46vw, 640px); }
.console-description { pointer-events: none; color: #fff; font-size: clamp(12px, min(1.08vw, 1.85vh), 21px); line-height: 1.45; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-shadow: 0 1px 2px #00112ce0, 0 0 7px #00112c99, 0 2px 12px #00112ccc; animation: consoleDescriptionIn 420ms 100ms both; }
.from-right { animation: consoleItemsRight 300ms ease both; }
.from-left { animation: consoleItemsLeft 300ms ease both; }
@keyframes consoleDescriptionIn { from { opacity: 0; transform: translateX(6px); } to { opacity: 1; transform: none; } }
@keyframes consoleItemsRight { from { opacity: 0; margin-left: 18px; } to { opacity: 1; margin-left: 0; } }
@keyframes consoleItemsLeft { from { opacity: 0; margin-left: -18px; } to { opacity: 1; margin-left: 0; } }

/* The console's clock: a bar open toward the right edge — no box, the date
   simply ends at the rail, as on the hardware. The fixed width and the
   position (top 60px, right 48px) are identical on every screen. The
   previous closed 300×48 box is kept behind --clock-box for comparison. */
.console-clock { --clock-box: 0; position: absolute; z-index: 60; right: var(--rail-right); top: 60px; display: flex; align-items: center; justify-content: flex-end; gap: 0.6em; min-width: calc(300px * var(--clock-box)); min-height: calc(48px * var(--clock-box)); padding: calc(8px * var(--clock-box)) calc(1.2em * var(--clock-box)) calc(8px * var(--clock-box)) 0; color: #f0f5f9dc; font-size: clamp(14px, min(1.6vw, 2.6vh), 26px); font-weight: 400; font-variant-numeric: tabular-nums; border: calc(1px * var(--clock-box)) solid #d5eff529; text-shadow: 0 1px 3px #0006; }
.console-clock::after { content: ""; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(180deg, #ecffff05, transparent); box-shadow: inset 0 1px 2px #ecffff05, 0 1px 0 #d9f4ff06; opacity: var(--clock-box); }
.console-clock svg { width: 0.95em; height: 0.95em; }

.console-status { position: absolute; z-index: 63; top: var(--status-top); right: var(--rail-right); width: var(--status-width); height: var(--status-height); display: flex; flex-direction: column; padding: 4px 10px; border: 1px solid #ffffff66; border-radius: 0; background: transparent; color: #fff; font-family: var(--font-xmb); font-weight: 400; font-synthesis: none; }
.console-status-row { display: flex; align-items: center; gap: 8px; min-height: 44px; flex: none; }
.console-status-user { display: inline-flex; align-items: center; gap: 4px; flex: none; font-size: 13px; font-variant-numeric: tabular-nums; }
.console-status-user svg { width: 22px; height: 22px; }
.console-status .console-clock { position: static; display: block; flex: 1; min-width: 0; min-height: 0; padding: 0; border: 0; font-size: clamp(14px, 1.2vw, 20px); line-height: 1.2; text-align: right; white-space: nowrap; color: #fff; text-shadow: none; }
.console-status .console-clock::after { display: none; }
.console-status-ticker { min-width: 0; overflow: hidden; line-height: 22px; font-size: clamp(12px, 1.05vw, 18px); }
.console-status-track { display: flex; gap: 32px; width: max-content; }
.console-status-track > span { flex: none; white-space: nowrap; }
.console-status-track[data-scroll="true"] { animation: consoleTicker var(--ticker-duration) linear infinite; }
.console-status:hover .console-status-track, .console-status:focus-within .console-status-track { animation-play-state: paused; }
@keyframes consoleTicker { from { transform: translateX(0); } to { transform: translateX(var(--ticker-shift)); } }
.console-environment:is([data-boot="gate"], [data-boot="playing"]) .console-status { opacity: 0; visibility: hidden; }
.console-environment[data-boot="handoff"] .console-status { animation: bootChromeIn 1.4s ease both; }
@media (prefers-reduced-motion: reduce) {
  .console-status-track[data-scroll="true"] { display: block; width: 100%; animation: none; transform: none; }
  .console-status-track > span:first-child { display: block; overflow: hidden; text-overflow: ellipsis; }
  .console-status-track > span[aria-hidden="true"] { display: none; }
}
/* The notification list: the hardware keeps a circular information button
   in the top right corner, and pressing it opens the pending items as a
   Settings-style list floating over the waves — no panel, no card. The
   selected entry sits at the menu's own anchor line, larger and brighter,
   with its value to the right of the subject and its description underneath;
   the entries around it step away and fade, as on the hardware. Here the
   pending items are the repository's own commits. */
.console-notice-toggle { position: absolute; z-index: 63; right: var(--rail-right); top: 12px; width: 3.9vh; height: 3.9vh; min-width: 26px; min-height: 26px; display: grid; place-items: center; padding: 0; border: 0; background: transparent; color: #dcecf8c4; opacity: 0.82; cursor: pointer; transition: color 200ms ease, opacity 200ms ease, transform 240ms ease; }
.console-notice-toggle svg { width: 100%; height: 100%; }
.console-notice-toggle:hover { color: #fff; opacity: 1; }
.console-notice-toggle[data-open="true"] { color: #fff; opacity: 1; }
.console-notice-dot { position: absolute; top: 2%; right: 2%; width: 20%; height: 20%; border-radius: 50%; background: #c6e9ff; box-shadow: 0 0 7px #9fd8ff9e; transition: opacity 200ms ease; }
.console-notice-dot[data-on="false"] { opacity: 0; }
.console-notice-panel { --notice-font: clamp(14px, min(1.4vw, 2.3vh), 30px); --notice-step: clamp(44px, 6.8vh, 84px); position: absolute; z-index: 62; inset: 0; overflow: hidden; opacity: 0; visibility: hidden; pointer-events: none; transform: scale(1.03) translateX(-0.8vw); transition: transform 420ms cubic-bezier(0.16, 1, 0.3, 1), opacity 260ms ease, visibility 0s 420ms; }
.console-notice-panel[data-open="true"] { opacity: 1; visibility: visible; pointer-events: auto; transform: none; transition: transform 420ms cubic-bezier(0.16, 1, 0.3, 1), opacity 260ms ease; }
/* The section mark: back chevron and large icon, level with the selected
   entry, the way the hardware parks its category icon beside the list. */
.console-notice-rail { position: absolute; left: 9vw; top: var(--selected-y); display: flex; align-items: center; gap: 14px; transform: translateY(-50%); }
.console-notice-back { display: grid; place-items: center; width: 30px; height: 30px; padding: 0; border: 0; background: transparent; color: #dcecf8c4; font-size: 30px; line-height: 1; cursor: pointer; }
.console-notice-back:hover { color: #fff; }
.console-notice-rail-icon { display: block; width: var(--item-size); height: var(--item-size); filter: drop-shadow(0 3px 2px #0006) drop-shadow(0 0 7px #daeaff29); }
.console-notice-rail-icon svg { display: block; width: 100%; height: 100%; }
/* The list owns the whole column of the screen, and a gradient mask keeps
   its edges clear: entries dissolve before the top of the screen and are
   fully gone well above the footer's safe area, so no row ever lands on
   the chrome below — the footer line stays free of every entry. */
.console-notice-list { position: absolute; left: var(--anchor-x); top: 0; width: calc(100% - var(--anchor-x) - 5vw); height: 100%; margin: 0; padding: 0; list-style: none; -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 8vh, #000 72vh, transparent 84vh); mask-image: linear-gradient(to bottom, transparent 0, #000 8vh, #000 72vh, transparent 84vh); }
/* The console's list, shared by the information board and the Settings
   screens. Full mode: the rows hang on the list's centre line, the selected
   entry enlarged and fully opaque, the others stepping away and fading —
   exactly the geometry the board always used. Compact mode: the same rows
   in document flow, for pages that scroll. */
.xmb-list { margin: 0; padding: 0; list-style: none; }
.xmb-list-row { position: absolute; left: 0; top: var(--selected-y); width: 100%; z-index: 1; transform: translate3d(0, calc(var(--row-offset, 0) * var(--notice-step, 72px)), 0); transition: transform 350ms cubic-bezier(0.22, 0.75, 0.25, 1), opacity 280ms ease; }
.xmb-list-row.is-selected { z-index: 3; }
.xmb-list-link { display: flex; align-items: flex-start; gap: clamp(14px, 1.2vw, 24px); width: 100%; padding: 0; border: 0; background: transparent; color: #dbe9f6; font-family: inherit; font-size: max(calc(var(--notice-font, 24px) * var(--item-scale, 1)), 12px); line-height: 1.35; text-align: left; text-decoration: none; cursor: pointer; transition: color 180ms ease; }
.xmb-list-link:hover, .xmb-list-row.is-selected .xmb-list-link { color: #fff; }
/* The enlarged, brightened row is the cursor: the hardware draws no ring
   around its selection, so neither do we. */
.xmb-list-link:focus-visible { outline: none; }
.xmb-list-icon { flex: none; width: 1.25em; height: 1.25em; margin-top: 0.12em; filter: drop-shadow(0 2px 2px #0006); }
.xmb-list-icon svg { display: block; width: 100%; height: 100%; }
.xmb-list-swatch { display: block; width: 1.7em; height: 1.15em; border-radius: 3px; border: 1px solid #d5eff552; box-shadow: 0 1px 3px #0007; }
/* Unread entries carry one small bright dot; it disappears once the
   cursor selects the entry, as the hardware marks the new. */
.xmb-list-new { flex: none; width: 0.3em; height: 0.3em; margin-top: 0.62em; border-radius: 50%; background: #cfe9ff; box-shadow: 0 0 6px #9fd8ff99; }
.xmb-list-row:not(.is-selected) .xmb-list-new { opacity: 0.55; }
.xmb-list-body { display: flex; flex: 1; flex-direction: column; gap: 0.22em; min-width: 0; }
.xmb-list-top { display: flex; align-items: baseline; gap: 20px; width: 100%; min-width: 0; }
/* Every title runs one line, cut with an ellipsis at the list's edge; the
   small sub (a merge's branch) drops to a second line inside the title. */
.xmb-list-title { display: flex; flex-wrap: wrap; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-shadow: 0 2px 3px #00112c88; }
.xmb-list-row.is-selected .xmb-list-title { text-shadow: 0 1px 4px #f3faff50, 0 2px 5px #0006; }
.xmb-list-sub { display: block; width: 100%; margin-top: 1px; font-size: 0.6em; opacity: 0.66; }
/* Fixed right column, tabular: dates, states, the console's own numbers. */
.xmb-list-meta { flex: none; margin-left: auto; width: 13ch; text-align: right; font-size: 0.68em; letter-spacing: 0.04em; color: #cfe4f4cc; font-variant-numeric: tabular-nums; }
.xmb-list-row:not(.is-selected) .xmb-list-meta { opacity: 0.8; }
/* A Settings screen's key/value row: the key at the left, the value at the
   right, wrapping, the selected row standing larger. */
