/* The selected entry's description, underneath its subject. */
.xmb-list-detail { max-width: min(46vw, 640px); font-size: 0.62em; line-height: 1.5; color: #cfe2f2; text-shadow: 0 1px 3px #000a; animation: consoleDescriptionIn 420ms 100ms both; }
.console-notice-sha { font-family: var(--font-mono); color: #a8cbe2b8; }

.console-commit { position: absolute; inset: max(100px, 16dvh) 8vw 16dvh; display: flex; flex-direction: column; min-height: 0; color: #eaf4fc; text-shadow: 0 1px 3px #0009; }
.console-commit > .console-back { align-self: flex-start; flex: none; margin-bottom: 16px; }
.console-commit-content { min-height: 0; overflow: auto; overscroll-behavior: contain; padding: 5px 12px 20px 5px; scrollbar-width: thin; }
.console-commit h2 { margin: 0 0 20px; font-size: clamp(20px, 2.5vw, 34px); font-weight: 400; line-height: 1.35; overflow-wrap: anywhere; }
.console-commit h3 { margin: 24px 0 12px; font-size: 17px; font-weight: 400; }
.console-commit-meta { display: grid; gap: 8px; font-size: 13px; }
.console-commit-meta > div { display: grid; grid-template-columns: 65px minmax(0, 1fr); gap: 16px; }
