.console-commit-file pre { max-height: 45dvh; overflow: auto; padding: 12px; background: #03132c66; font-family: var(--font-mono); font-size: 12px; line-height: 1.6; text-shadow: none; }
.console-commit-file code { font-family: var(--font-mono); }
.console-commit-source { display: inline-block; margin-top: 24px; font-size: 13px; text-decoration: underline; text-underline-offset: 4px; }
.console-commit :focus-visible { outline: 1.5px solid #dfedf9; outline-offset: 2px; }
.console-commit h2:focus { outline: none; }

/* Compact mode: the same rows in document flow, for the Settings screens.
   The cursor row stands a size larger, as on the hardware. */
.xmb-list--compact { position: static; }
.xmb-list--compact .xmb-list-row { position: static; top: auto; width: auto; z-index: auto; transform: none; opacity: 1; transition: none; }
