.xmb-list--compact .xmb-list-detail { max-width: none; font-size: 0.92em; animation: none; }
.xmb-list--compact .xmb-list-value { font-size: 0.85em; }

/* The Settings screens: a lede, the console's list, a small note. Nothing
   else — no cards, no pills, no header panel. The wave shows through. */
.settings-screen { display: flex; flex-direction: column; gap: 16px; }
.settings-lede { margin: 0; max-width: 660px; font-family: var(--font-xmb); font-size: 16px; line-height: 1.55; color: #dbe9f5; text-shadow: 0 1px 2px #0008; }
.settings-list { --xmb-list-font: 15.5px; padding: 12px 0; }
.settings-note { margin: 0; font-family: var(--font-xmb); font-size: 12.5px; line-height: 1.6; color: #9fb9cf; text-shadow: 0 1px 2px #0008; }
.settings-note a, .xmb-code-link { color: #c6e3f2; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: #b8d9ee4d; }
.settings-note a:hover, .xmb-code-link:hover { color: #fff; text-decoration-color: #b8d9ee; }
.xmb-code-link { font-family: var(--font-mono); font-size: 11px; }
.xmb-config-detail { display: grid; gap: 8px; justify-items: start; }
.xmb-config-warn { color: #9fb9cf; font-size: 0.85em; }
.theme-settings-list { --xmb-list-font: 16px; padding: 12px 0; }
/* The list takes the screen: behind it the waves stand alone, the way the
   reference screen shows nothing but the list and its rail. The menu, the
   wordmark and the key hints sink into the background; the clock stays up
   top, as the hardware keeps its clock on that corner. */
.console-environment[data-notices="open"] :is(.console-menu, .console-application) { visibility: hidden; pointer-events: none; }
.console-environment[data-notices="open"] :is(.console-identity[data-hidden="false"], .console-help) { opacity: 0.2; }
.console-environment[data-notices="open"] .console-options { opacity: 0; visibility: hidden; pointer-events: none; }
/* New-commit toasts: an icon and one line of text, the menu's own shadow,
   no box — the way the hardware announces things on the waves. They are
