   comparison (0 = frameless, the default; 1 = the bar). */
.console-toast-region { position: absolute; z-index: 64; top: 118px; right: var(--rail-right); width: min(420px, 60vw); pointer-events: none; }
.console-toast { --toast-bar: 0; display: flex; align-items: center; gap: 12px; padding: 9px 2px 9px 0; color: #eef6fd; background: rgba(6, 22, 40, calc(0.78 * var(--toast-bar))); border: 1px solid rgba(213, 239, 245, calc(0.19 * var(--toast-bar))); border-radius: calc(10px * var(--toast-bar)); box-shadow: 0 10px 30px rgba(0, 0, 0, calc(0.44 * var(--toast-bar))); backdrop-filter: blur(calc(6px * var(--toast-bar))); animation: consoleToastIn 340ms cubic-bezier(0.16, 1, 0.3, 1) both; }
.console-toast[data-leaving="true"] { animation: consoleToastOut 300ms ease both; }
