.console-toast-icon svg { display: block; width: 100%; height: 100%; }
.console-toast-text { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 14px; letter-spacing: 0.02em; text-shadow: 0 1px 2px #00112ce0, 0 0 7px #00112c99, 0 2px 12px #00112ccc; }
@keyframes consoleToastIn { from { opacity: 0; transform: translateX(18px); } to { opacity: 1; transform: none; } }
@keyframes consoleToastOut { to { opacity: 0; transform: translateY(-6px); } }

/* The △ options panel: a small list anchored at the right edge, on the
   selected destination only. It slides in from the edge and slides back
   when ○/Esc closes it; the selected row steps forward and brightens. */
.console-options { --options-font: clamp(14px, min(1.25vw, 2.1vh), 24px); position: absolute; z-index: 61; top: 50%; right: var(--rail-right); width: min(380px, 62vw); opacity: 0; visibility: hidden; pointer-events: none; transform: translate(105%, -50%); transition: transform 300ms cubic-bezier(0.16, 1, 0.3, 1), opacity 240ms ease, visibility 0s 300ms; }
