.console-option { display: flex; width: 100%; align-items: center; gap: 14px; padding: 10px 18px; border: 0; background: transparent; color: #cfe3f2; font-size: var(--options-font); text-align: left; cursor: pointer; opacity: 0.72; text-shadow: 0 1px 3px #00112c99; transition: color 160ms ease, opacity 160ms ease, transform 200ms ease; }
.console-option.is-selected { color: #fff; opacity: 1; transform: translateX(-6px); text-shadow: 0 1px 4px #f3faff50, 0 2px 5px #0006; }
.console-option-icon { width: 1.1em; height: 1.1em; flex: none; filter: drop-shadow(0 1px 2px #0008); }
.console-option-icon svg { display: block; width: 100%; height: 100%; }
.console-options-detail { margin: 8px 18px 4px; padding: 0; max-width: 360px; font-size: calc(var(--options-font) * 0.66); line-height: 1.5; color: #d3e4f4; text-shadow: 0 1px 3px #000a; }

.console-identity { position: absolute; z-index: 20; left: var(--rail-right); bottom: 5.6vh; display: flex; align-items: center; gap: 1em; color: #d5e4f1c0; transition: opacity 220ms; }
.console-identity[data-hidden="true"] { opacity: 0; pointer-events: none; }
.console-wordmark { font-family: var(--font-xmb), sans-serif; font-size: clamp(20px, min(2vw, 3.2vh), 46px); font-weight: 400; letter-spacing: 0.08em; text-shadow: 0 1px 2px #0005; border: 0; padding: 0; background: transparent; color: inherit; cursor: pointer; }
