.console-identity-caption { display: flex; flex-direction: column; gap: 3px; font-size: clamp(11px, min(0.85vw, 1.4vh), 20px); color: #b3cadc9c; }
.console-identity-caption > span { font-size: 0.92em; color: #b3cadc7d; }
.console-sound { display: flex; align-items: center; gap: 6px; margin-left: 0; padding: 5px; border: 0; background: transparent; color: #b3cadc99; font-size: clamp(11px, 0.72vw, 19px); }
.console-sound:hover { color: #edf6ff; }
.console-sound svg { width: 1.4em; height: 1.4em; }
