.console-help button { display: inline-flex; align-items: center; gap: 0.35em; padding: 0; border: 0; background: none; color: inherit; font-size: inherit; }
.console-help button:hover { color: white; }
.console-help kbd, .console-app-back-hint kbd { font: inherit; }
.console-help kbd { margin-right: 0.4em; font-size: 1.2em; }
.console-help-arrows { margin-right: -0.6em; letter-spacing: 0.12em; }

/* Applications take over the entire screen, rather than opening beside a sidebar.
   The backdrop is a veil, not a lid: the blurred waves still read through it. */
.console-application { position: absolute; z-index: 30; inset: 0; display: flex; flex-direction: column; padding: 3.7vh 5.7vw 0; background: linear-gradient(180deg, rgba(3, 19, 44, 0.36), rgba(4, 20, 44, 0.14) 38%, rgba(3, 19, 44, 0.26)); animation: consoleAppIn 460ms cubic-bezier(0.16, 1, 0.3, 1) both; }
/* Application content wears the console's own face, one weight; monospace
   appears only where code does. */
.console-application-content { font-family: "SCE-PS3 Rodin LATIN", "XMB Noto Adjusted", "Noto Sans", "Helvetica Neue", Arial, sans-serif; font-synthesis: none; }
.console-application-content pre, .console-application-content code { font-family: var(--font-mono); }
.console-application.is-leaving { animation: consoleAppOut 240ms ease both; pointer-events: none; }
.console-application-header { display: flex; flex-shrink: 0; align-items: center; gap: 18px; height: clamp(74px, 10.5vh, 160px); padding-right: 28vw; margin-bottom: 1vh; color: #edf4fa; }
.console-back { display: flex; align-items: center; gap: 9px; border: 0; margin-right: 20px; padding: 8px 0; background: transparent; color: #c7d9e6; font-size: 14px; }
.console-back:hover { color: white; }
.console-back .controller-glyph { width: 26px; height: 26px; }
.console-app-icon { width: 36px; height: 36px; flex-shrink: 0; }
.console-app-category { margin: 0 0 3px; font-size: 11px; color: #8faabf; }
.console-application-header h2 { margin: 0; font-size: 17px; font-weight: 400; }
.console-application-content { outline: none; min-height: 0; flex: 1; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; padding-bottom: 25px; }
.console-app-content-enter { max-width: 1800px; margin: 0 auto; animation: consoleContentIn 440ms ease both; }
.console-app-colophon { max-width: 1740px; margin: 10px auto 0; padding: 16px 20px; border-top: 1px solid #ccdeec10; color: #8ca8be; font-size: 11px; }
.console-app-back-hint { align-self: flex-end; display: flex; align-items: center; gap: 10px; height: 5.6vh; min-height: 40px; padding: 0; background: transparent; border: 0; font-size: 12px; color: #b9cfdf; }
.controller-glyph { display: inline-block; width: 1.45em; height: 1.45em; flex: none; vertical-align: middle; }
.console-app-back-hint kbd { margin-left: 7px; font-size: 10px; opacity: 0.65; }
@keyframes consoleAppIn { from { opacity: 0; transform: scale(1.025) translateY(9px); } to { opacity: 1; transform: none; } }
@keyframes consoleAppOut { to { opacity: 0; transform: scale(0.97) translateY(6px); } }
@keyframes consoleContentIn { from { opacity: 0; transform: translateX(16px); } to { opacity: 1; transform: none; } }

/* System screens share one row field, one text panel and the console controls. */
.console-environment[data-surface="app"] { --status-top: clamp(24px, 3.7vh, 40px); --status-width: clamp(300px, 26vw, 420px); --status-height: 72px; }
.console-environment[data-surface="app"] .console-status { border-color: #ffffffbf; }
.console-environment[data-surface="app"] .console-status-ticker { line-height: 18px; font-size: clamp(11px, 0.9vw, 15px); }
.console-application { padding-bottom: max(12px, env(safe-area-inset-bottom)); background: none; animation: xmbApplicationIn 320ms ease-out both; }
.console-application.is-leaving { animation: xmbApplicationOut 240ms ease-out both; }
.console-application-header { height: clamp(72px, 9vh, 100px); padding-right: calc(var(--status-width) + 12px); margin-bottom: 12px; gap: 16px; }
.console-application-header h1 { margin: 0; font-size: 24px; line-height: 1.3; font-weight: 400; }
.console-application-header, .console-app-hints { font-family: var(--font-xmb); font-synthesis: none; }
.console-app-category { font-size: 12px; color: #ffffffcc; line-height: 1.4; }
.console-app-icon { width: 44px; height: 44px; color: white; filter: drop-shadow(0 0 5px #ffffff35); }
.console-app-body { position: relative; flex: 1; min-height: 0; min-width: 0; margin-left: 6.8vw; }
.console-application-content { height: 100%; padding: 12px 24px 24px 0; overflow-x: hidden; overflow-wrap: anywhere; scrollbar-width: none; color: #fff; font-weight: 400; -webkit-mask-image: linear-gradient(transparent, #000 12px, #000 calc(100% - 18px), transparent); mask-image: linear-gradient(transparent, #000 12px, #000 calc(100% - 18px), transparent); }
.console-application-content::-webkit-scrollbar, .console-application-content ::-webkit-scrollbar { display: none; width: 0; height: 0; }
.console-application-content * { scrollbar-width: none; font-weight: 400; }
.console-application-content :is(.font-semibold, .font-medium, .font-bold, b, strong) { font-weight: 400; }
.console-application-content :is(.label, .tracking-wider, .tracking-widest, .uppercase) { text-transform: none; letter-spacing: normal; }
.console-application-content :is(.text-muted, .text-faint, .text-amber) { color: #ffffffb8; }
.console-application-content :is(h2, h3) { font-weight: 400; }
.console-application-content .display { font-size: 20px; }
.console-application-content .display em { color: inherit; }
.console-application-content .xmb-column-head { color: #fff; }
.console-application-content .xmb-column-head svg { opacity: 0.8; filter: drop-shadow(0 0 4px #ffffff30); }
.console-application-content [role="button"]:focus { outline: 1.5px solid #fff; outline-offset: 4px; }
.console-application-content .xmb-row:hover { background: #ffffff09; }
.console-application-content .xmb-quote { border: 0; padding: 0; text-shadow: none; }
.console-application-content pre { white-space: pre-wrap; overflow-wrap: anywhere; }
.console-application-content :is(.grid, .flex) > * { min-width: 0; }
.console-application-content pre .whitespace-pre { white-space: pre-wrap; }
.console-app-content-enter { height: 100%; max-width: 1700px; animation: none; }
.console-app-body:has(.xmb-screen) { width: min(59.375vw, 1140px); }
.console-application-content:has(.xmb-screen) { overflow: hidden; padding: 0 24px 0 0; mask-image: none; -webkit-mask-image: none; }
.console-app-body:has(.xmb-screen) > .xmb-scroll-indicators { display: none; }
.xmb-screen { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(140px, 1fr) auto auto; gap: 10px; height: 100%; min-width: 0; }
.xmb-screen-subtitle { margin: 0; font-size: 14px; line-height: 1.5; color: #ffffffcc; font-weight: 400; }
.xmb-section-navigation { display: flex; align-items: center; flex-wrap: wrap; gap: 0 20px; min-height: 32px; border-bottom: 1px solid #ffffff33; }
.xmb-section-navigation button { min-height: 32px; padding: 4px 0; border: 0; background: none; color: #ffffff80; font: inherit; font-size: 12px; text-align: left; }
.xmb-section-navigation button[aria-pressed="true"] { color: #fff; }
.xmb-section-controls { margin-left: auto; white-space: nowrap; font-size: 10px; opacity: 0.5; }
.xmb-screen-list-region { position: relative; min-height: 0; }
.xmb-list--screen { position: relative; height: 100%; overflow: auto; overflow-anchor: none; overscroll-behavior: contain; padding: max(0px, calc(var(--screen-list-half, 120px) - 22px)) 8px max(0px, calc(var(--screen-list-bottom, 120px) - 22px)); scrollbar-width: none; -webkit-mask-image: linear-gradient(transparent, #000 18px, #000 calc(100% - 18px), transparent); mask-image: linear-gradient(transparent, #000 18px, #000 calc(100% - 18px), transparent); }
.xmb-list--screen .xmb-list-row { position: relative; top: auto; left: auto; height: 44px; width: 100%; transform: none; transition: opacity 180ms ease; }
.xmb-list--screen .xmb-list-row[data-anchor-selected="true"] { height: 66px; margin: 10px 0; }
