.console-app-hints { display: flex; flex: none; align-self: flex-end; align-items: center; gap: 22px; min-height: 44px; margin-top: 8px; color: #fff; opacity: 0.8; transition: opacity 350ms ease; font-size: 14px; }
.console-app-hints button { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; padding: 0; border: 0; background: none; font: inherit; }
