@keyframes xmbApplicationIn { from { opacity: 0; transform: translate(20px, 12px); } to { opacity: 1; transform: none; } }
@keyframes xmbApplicationOut { to { opacity: 0; transform: translate(20px, 12px); } }
@media (max-width: 759px) {
