/* The XMB uses one regular font weight. Application content keeps its own fonts. */
:is(.console-menu, .console-clock, .console-identity, .console-help, .console-back, .console-app-back-hint, .console-app-category, .console-application-header h2, .boot-screen, .console-audio-panel, .console-notice-toggle, .console-notice-panel, .console-options) {
  font-family: "SCE-PS3 Rodin LATIN", "XMB Noto Adjusted", "Noto Sans", "Helvetica Neue", Arial, sans-serif;
  font-synthesis: none;
  font-style: normal;
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  text-shadow: 0 1px 3px #0008;
}
:is(.console-menu, .console-clock, .console-identity, .console-help, .boot-screen, .console-audio-panel, .console-notice-panel, .console-notice-toggle, .console-options) :is(button, a, span, p, time, input) {
  font-family: inherit;
  font-synthesis: none;
  font-style: normal;
  font-weight: 400;
  letter-spacing: normal;
}
.console-category-label { font-family: inherit; }
.console-wordmark { font-weight: 400; letter-spacing: normal; }
.console-identity .console-wordmark { font-family: var(--font-xmb), sans-serif; color: #f0f6fd; text-shadow: 0 1px 2px #0006, 0 0 16px #cfe8ff2e; }

/* The boot overlay contains only typography; the wallpaper underneath never changes canvas. */
.boot-screen { position: absolute; inset: 0; z-index: 70; pointer-events: none; color: #fff; }
.boot-screen[data-running="false"] { pointer-events: auto; }
.boot-gate { position: absolute; left: 50%; top: 67%; transform: translateX(-50%); width: min(90vw, 520px); border: 0; padding: 14px; background: transparent; color: #f7f3fa; font-size: clamp(13px, 0.95vw, 18px); text-align: center; text-shadow: 0 0 15px #dcc6ec40; }
.boot-gate:hover { color: #fff; text-shadow: 0 0 20px #ebdafa90; }
.boot-gate span { display: block; margin-top: 8px; color: #c1b4ca; font-size: 0.76em; }
.boot-brand { position: absolute; left: 60%; top: 45.5%; width: 30%; text-align: center; opacity: 0; animation: bootBrand 6.2s linear both; }
.boot-wordmark { width: min(100%, 520px); margin: 0 auto; }
.boot-wordmark svg, .boot-wordmark img { display: block; width: 100%; height: auto; fill: #fff; }
.boot-subtitle { margin-top: 1vh; color: #fff; font-size: clamp(10px, 0.83vw, 17px); letter-spacing: 0.06em !important; text-shadow: 0 0 5px #fff3; }
.boot-subtitle img { display: block; width: min(70%, 260px); height: auto; margin: 0 auto; }
.boot-wordmark-text { display: block; color: #fff; font-size: clamp(58px, 7.4vw, 136px); line-height: 0.9; letter-spacing: 0.1em; text-align: center; font-synthesis: none; text-shadow: 0 0 8px #fff4; }
.boot-screen[data-paused="true"] .boot-brand { animation-play-state: paused; }
.boot-screen[data-skipping="true"] .boot-brand { animation: none; opacity: 0; transition: opacity 0.3s ease; }
@keyframes bootBrand {
  0%, 25.8% { opacity: 0; transform: translateX(-6px); filter: drop-shadow(0 0 24px #fff); }
  46.8%, 77.4% { opacity: 1; transform: translateX(0); filter: drop-shadow(0 0 5px #fff7); }
  100% { opacity: 0; transform: translateX(2px); filter: drop-shadow(0 0 26px #fff); }
}
@keyframes bootBrandReduced {
  0%, 12% { opacity: 0; }
  28%, 70% { opacity: 1; }
  100% { opacity: 0; }
}
@keyframes bootMenuIn { from { opacity: 0; transform: scale(1.04); } to { opacity: 1; transform: scale(1); } }
@keyframes bootChromeIn { from { opacity: 0; } to { opacity: 1; } }
.console-environment:is([data-boot="gate"], [data-boot="playing"]) :is(.console-menu, .console-clock, .console-identity, .console-help, .console-application, .console-notice-toggle, .console-notice-panel, .console-options) { opacity: 0 !important; visibility: hidden !important; }
.console-environment[data-boot="handoff"] .console-menu[data-hidden="false"] { animation: bootMenuIn 1.4s cubic-bezier(0.2, 0.75, 0.25, 1) both; }
.console-environment[data-boot="handoff"] :is(.console-clock, .console-help, .console-identity[data-hidden="false"], .console-application, .console-notice-toggle, .console-options) { animation: bootChromeIn 1.4s ease both; }
.console-environment[data-skipping="true"] :is(.console-menu, .console-clock, .console-help, .console-identity, .console-application, .console-notice-toggle, .console-options) { animation-duration: 0.35s; }

/* Separate music/effects controls; the trigger also supports a long press to replay. */
.console-audio { position: relative; }
.console-audio-panel { position: absolute; bottom: calc(100% + 14px); left: 1vw; width: 242px; padding: 13px 15px; color: #eef4fa; background: #09203bea; border: 1px solid #d5eff536; box-shadow: 0 10px 35px #0007; font-size: 12px; text-shadow: 0 1px 3px #0008; }
.console-audio-title { margin: 0 0 8px; color: #fff; }
.console-audio-panel button, .console-audio-panel label { display: block; width: 100%; padding: 8px 0; border: 0; border-top: 1px solid #d5eff51e; background: transparent; color: #cbdbe8; text-align: left; font-size: inherit; }
.console-audio-panel button:hover { color: #fff; }
.console-audio-panel button span, .console-audio-panel label span { float: right; color: #9eb9cd; }
.console-audio-panel input { display: block; width: 100%; margin: 9px 0 2px; accent-color: #c6e3f2; }

/* Reusable technical tools remain inside the full-screen applications. */
@layer components {
  /* Page text wears the console's own face: Rodin, one weight, no decorative
     uppercase. Monospace is reserved for code blocks. */
  .label { font-family: var(--font-xmb); font-size: 12px; line-height: 1.5; letter-spacing: 0.04em; color: #9fc0d8; }
  .display { font-family: var(--font-xmb); font-weight: 400; line-height: 1.25; letter-spacing: 0.01em; }
  h1 em, h2 em, .display em { font-style: normal; font-weight: 400; color: #c6e3f2; }
  .schematic-grid { background-image: radial-gradient(#b3d6ed14 0.6px, transparent 0.8px); background-size: 28px 28px; }
  .micro-grid { background-image: radial-gradient(#b3d6ed10 0.6px, transparent 0.8px); background-size: 14px 14px; }
  .hatch-rust { background-image: repeating-linear-gradient(-45deg, #e4a09216 0 1px, transparent 1px 7px); }
  .hatch-amber { background-image: repeating-linear-gradient(-45deg, #b3d6ed14 0 1px, transparent 1px 7px); }
  .btn { display: inline-flex; align-items: center; justify-content: center; gap: 0.55rem; border-radius: 3px; font-size: 12px; font-weight: 400; padding: 0.65rem 1.1rem; transition: background 180ms, color 180ms, border-color 180ms; }
  .btn-primary { background: #dfe8ef; color: #172c40; border: 1px solid #f0f6fc; }
  .btn-primary:hover { background: #fff; }
  .btn-amber { background: #a4d1e812; color: #e6eff5; border: 1px solid #b8d9ee52; }
  .btn-amber:hover { background: #a4d1e826; }
  .btn-outline { background: transparent; color: #d4e4ee; border: 1px solid #bfd9e947; }
  .btn-outline:hover { border-color: #dfefff; color: white; }
  .btn-ghost { background: transparent; color: #a9c3d7; border: 1px solid transparent; }
  .btn-ghost:hover { color: white; background: #d7e9f408; }
  .code-scroll { scrollbar-width: thin; scrollbar-color: #afcde63a transparent; }
  .code-scroll::-webkit-scrollbar { width: 6px; height: 6px; }
  .code-scroll::-webkit-scrollbar-thumb { background: #afcde63a; }
  .tok-com { color: #829aae; font-style: italic; }
  .tok-str { color: #b7d6b7; }
  .tok-kw { color: #abd4f1; }
  .tok-type { color: #c5cbe8; }
  .tok-num { color: #dfb995; }
  .tok-fn { color: #eaf4ff; }
  .reveal { opacity: 0; transform: translateY(10px); transition: opacity 500ms ease, transform 500ms ease; }
  .reveal[data-visible="true"] { opacity: 1; transform: none; }
  .signal-flow { stroke-dasharray: 10 110; animation: signalDash 2.8s linear infinite; }
  .signal-flow-slow { stroke-dasharray: 8 132; animation: signalDash 4.2s linear infinite; }
  @keyframes signalDash { from { stroke-dashoffset: 120; } to { stroke-dashoffset: 0; } }
  /* XMB PAGE FURNITURE. The documents are Settings screens, not pages of
     cards: nothing carries a border, a box or a pill. Columns, rows, tiles
     and notes are laid straight on the blurred wave, in the console's own
     face, with a row cursor that brightens — the only feedback. */
  .xmb-glass { background: transparent; border: 0; box-shadow: none; }
  .xmb-surface { container-type: inline-size; container-name: xmbcol; }
  .xmb-column-head { display: flex; align-items: center; gap: 12px; padding: 11px 16px; }
  .xmb-column-head svg { width: 20px; height: 20px; flex: none; color: #cfe6f8; filter: drop-shadow(0 1px 2px #0007); }
  .xmb-column-title { font-family: var(--font-xmb); font-size: 16px; font-weight: 400; letter-spacing: .015em; color: #eaf4fc; text-shadow: 0 1px 2px #0009; }
  .xmb-column-note { margin-left: auto; font-family: var(--font-xmb); font-size: 12px; letter-spacing: .03em; color: #8fb6d6; text-shadow: 0 1px 2px #0009; }
  .xmb-column-lede { padding: 13px 16px 0; font-family: var(--font-xmb); font-size: 17px; line-height: 1.35; letter-spacing: .012em; color: #eef5fb; text-shadow: 0 1px 2px #0006; }
  .xmb-row { display: grid; grid-template-columns: 20px 150px minmax(0, 1fr); gap: 14px; align-items: center; padding: 10px 16px; transition: background 160ms ease; }
  .xmb-row:hover { background: linear-gradient(90deg, #a4d1e814 0%, #a4d1e805 45%, #a4d1e800 80%); }
  .xmb-row-icon { width: 20px; height: 20px; color: #a8cbe6; filter: drop-shadow(0 1px 2px #0007); transition: color 160ms ease; }
  .xmb-row:hover .xmb-row-icon { color: #eaf4fb; }
  .xmb-row-key { font-family: var(--font-xmb); font-size: 14px; line-height: 1.5; letter-spacing: .02em; color: #b9d2e5; text-shadow: 0 1px 2px #0008; }
  .xmb-row-value { font-family: var(--font-xmb); font-size: 14.5px; line-height: 1.55; color: #e8f1f9; text-shadow: 0 1px 2px #0008; }
  .xmb-row-value a { color: #cfe6f8; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: #b8d9ee4d; }
  .xmb-row-value a:hover { color: #fff; text-decoration-color: #b8d9ee; }
  .xmb-avatar { display: grid; place-items: center; width: 76px; height: 76px; flex: none; }
  .xmb-avatar svg { width: 44px; height: 44px; color: #dbeeff; filter: drop-shadow(0 2px 3px #0007); }
  .xmb-quote { border-left: 2px solid #b8d9ee4d; padding-left: 14px; font-family: var(--font-xmb); font-size: 14px; line-height: 1.7; color: #d5e6f4; text-shadow: 0 1px 2px #0008; }
  .xmb-tile { display: flex; gap: 13px; padding: 13px 15px; transition: background 180ms ease; }
  .xmb-tile:hover { background: #a4d1e80a; }
  .xmb-tile svg { width: 22px; height: 22px; flex: none; color: #a8cbe6; filter: drop-shadow(0 1px 2px #0007); transition: color 180ms ease; }
  .xmb-tile:hover svg { color: #eaf4fb; }
  .xmb-tile-title { font-family: var(--font-xmb); font-size: 14.5px; letter-spacing: .02em; color: #edf4fa; text-shadow: 0 1px 2px #0008; }
  .xmb-tile-sub { margin-top: 4px; font-family: var(--font-xmb); font-size: 12.5px; line-height: 1.55; color: #9fb9cf; text-shadow: 0 1px 2px #0008; }
  .xmb-note { display: flex; gap: 11px; padding: 10px 16px; font-family: var(--font-xmb); font-size: 13px; line-height: 1.6; color: #b6cadd; text-shadow: 0 1px 2px #0008; }
  .xmb-note::before { content: ""; width: 5px; height: 5px; margin-top: 7px; flex: none; background: #c6e3f2b3; transform: rotate(45deg); }
  .xmb-masthead { position: relative; }
  .xmb-masthead .display { font-family: var(--font-xmb); font-weight: 400; letter-spacing: .012em; }
  .xmb-masthead li { border-radius: 0; }
}

/* Page-level split: one column of panels until the document is wide enough
   to hold two, then the panels take their XMB column widths. */
.xmb-page-grid { display: grid; gap: 16px; }
.xmb-tile-grid { display: grid; gap: 8px; }

@media (min-width: 1120px) {
  .xmb-page-grid { grid-template-columns: repeat(12, minmax(0, 1fr)); }
  .xmb-span-4 { grid-column: span 4; }
  .xmb-span-5 { grid-column: span 5; }
  .xmb-span-7 { grid-column: span 7; }
  .xmb-span-8 { grid-column: span 8; }
}

/* Two tiles per row once the column itself is wide enough to carry them. */
@container xmbcol (min-width: 560px) {
  .xmb-tile-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* A column narrower than a label plus a value stacks its rows instead of
   squeezing the value into a sliver. */
@container xmbcol (max-width: 460px) {
  .xmb-row { grid-template-columns: 20px minmax(0, 1fr); gap: 3px 12px; }
  .xmb-row-key { grid-column: 2; }
  .xmb-row-value { grid-column: 2; }
}

@media (min-width: 2600px) {
  .console-environment { --category-size: 132px; --item-size: 126px; }
}
@media (max-width: 760px) {
  .console-environment { --anchor-x: 23vw; --category-y: 25vh; --selected-y: 45vh; --category-gap: 23vw; --category-size: 54px; --item-size: 52px; --item-step-base: 13.7vh; --rail-right: 16px; --label-gap: 22px; --menu-font: 21px; }
  .console-category-label { font-size: 13px; top: 36px; }
  .console-clock { top: 44px; font-size: 13px; }
  .console-destination-position { width: calc(100vw - var(--anchor-x) - 4vw + var(--item-size) / 2); }
  .console-destination-body { max-width: calc(100vw - var(--anchor-x) - var(--item-size) - var(--label-gap) - 10px); }
  .console-item-label { white-space: normal; }
  .console-description { font-size: 11.5px; }
  /* The footer is one clear line: the wordmark and audio sit on the left,
     the command icons on the right, both on the same baseline. The menu's
     rows are capped above 84vh by their step, so nothing reaches this line
     and the audio can never crowd the item column. */
  .console-identity { left: var(--rail-right); bottom: 4.6vh; gap: 8px; }
  .console-wordmark { font-size: 20px; }
  .console-identity-meta { flex-direction: row; align-items: center; gap: 4px; }
  .console-identity-caption { display: none; }
  .console-sound { margin-left: 0; font-size: 11px; }
  .console-sound > span { display: none; }
  .console-help { right: var(--rail-right); bottom: 4.6vh; font-size: 11px; gap: 1.1em; }
  /* On a phone the command bar keeps only its icons. */
  .console-help-arrows, .console-help-label { display: none; }
  .console-toast-region { top: 96px; width: calc(100vw - 2 * var(--rail-right)); }
  .console-notice-toggle { right: var(--rail-right); top: 8px; width: 32px; height: 32px; }
  .console-notice-panel { --notice-step: 6.4vh; --notice-font: 15px; }
  .console-notice-rail { left: 3vw; gap: 6px; }
  .console-notice-back { width: 24px; height: 24px; font-size: 24px; }
  .console-notice-list { width: calc(100% - var(--anchor-x) - 4vw); }
  .xmb-list-detail { max-width: calc(100vw - var(--anchor-x) - 52px); }
  .console-application { padding: 3vh 4vw 0; }
  .console-application-header { height: 95px; padding-right: 0; padding-top: 30px; gap: 12px; }
  .console-application-header h2 { font-size: 15px; }
  .console-back { margin-right: 3px; font-size: 12px; }
  .console-app-icon { width: 29px; height: 29px; }
  .console-app-category { font-size: 10px; }
  .console-app-back-hint { min-height: 42px; height: 42px; }
  .boot-brand { left: 32%; top: 44%; width: 62%; }
  .console-audio-panel { left: -85px; width: min(242px, 82vw); }
  .xmb-row { grid-template-columns: 20px minmax(0, 1fr); gap: 4px 12px; padding: 10px 13px; }
  .xmb-row-key { grid-column: 2; }
  .xmb-row-value { grid-column: 2; }
  .xmb-column-head { padding: 10px 13px; }
  .xmb-avatar { width: 62px; height: 62px; }
  .xmb-avatar svg { width: 36px; height: 36px; }
}
@media (pointer: coarse) {
  .console-help { display: none; }
}
@media (max-height: 480px) and (orientation: landscape) {
  .console-environment { --category-y: 23vh; --selected-y: 47vh; --item-step-base: 18vh; --category-size: 42px; --item-size: 38px; --menu-font: 16px; }
  .console-description { font-size: 12px; }
  .console-help { bottom: 5vh; }
  .console-identity { bottom: 5vh; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
  .reveal { opacity: 1 !important; transform: none !important; }
  .console-menu[data-hidden="true"] { transition-delay: 0s; }
  .boot-brand { animation-name: bootBrandReduced !important; animation-duration: 2.2s !important; }
  .console-environment[data-boot="handoff"] :is(.console-menu, .console-clock, .console-help, .console-identity, .console-application) { animation-duration: 0.55s !important; }
}

/* Hidden service mode: type "gateway", use the Konami code, or tap the wordmark five times. */
.easter-backdrop { position: fixed; inset: 0; z-index: 110; display: grid; place-items: center; padding: 20px; background: #010715b8; backdrop-filter: blur(5px); }
.easter-panel { width: min(620px, 100%); padding: 22px; border: 1px solid #cfe9ff40; background: #071c35f7; box-shadow: 0 30px 80px #0009, inset 0 1px 0 #fff1; color: #eaf4ff; font-family: var(--font-xmb); font-synthesis: none; text-shadow: 0 1px 3px #0008; }
.easter-head { display: flex; align-items: center; gap: 13px; padding-bottom: 14px; border-bottom: 1px solid #cfe9ff24; }
.easter-head p { margin: 0 0 2px; color: #94b2c9; font-size: 11px; letter-spacing: 0.08em; }
.easter-head h2 { margin: 0; font-size: 19px; font-weight: 400; }
.easter-head button { margin-left: auto; width: 32px; height: 32px; border: 1px solid #cfe9ff40; background: transparent; color: #d9e8f4; font-size: 16px; }
.easter-quote { margin: 20px 0; color: #fff; font-size: clamp(20px, 2.4vw, 29px); line-height: 1.25; }
.easter-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; margin-bottom: 18px; }
.easter-grid span { display: flex; align-items: center; gap: 9px; padding: 9px 10px; border: 1px solid #cfe9ff1f; color: #dceaf5; font-size: 12.5px; }
.easter-grid svg { width: 25px; height: 25px; flex: none; }
.easter-note { margin: 0 0 18px; color: #9bb6ca; font-size: 12px; line-height: 1.6; }
.easter-actions { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; padding-top: 14px; border-top: 1px solid #cfe9ff24; color: #88a5bb; font-size: 11px; }
.easter-actions button { padding: 8px 13px; border: 1px solid #cfe9ff4d; background: #c6e3f21a; color: #fff; font-size: 12px; }
.easter-actions button:hover { background: #c6e3f22e; }

/* TROPHIES, DIALOGS, ACTIVITY. Same glass as the toasts and the options panel. */
.trophy-toast { pointer-events: none; }
.trophies-list .xmb-list-sub { white-space: normal; overflow-wrap: anywhere; }

/* Input affordances share the console's existing type, colour and glyphs. */
.console-environment :is(button, a, summary, input) { touch-action: manipulation; }
.console-menu, .console-notice-panel[data-detail="false"] { touch-action: pinch-zoom; }
.console-options-dismiss { position: absolute; inset: 0; z-index: 60; border: 0; padding: 0; background: transparent; cursor: default; }
.console-options { max-height: 70dvh; overflow-y: auto; overscroll-behavior: contain; }
.console-option { min-height: 44px; }
.console-search-toggle { position: absolute; z-index: 63; top: 6px; right: calc(var(--rail-right) + 50px); display: grid; place-items: center; width: 44px; height: 44px; padding: 8px; border: 0; background: transparent; color: #dcecf8c4; }
.console-search-toggle svg { width: 24px; height: 24px; }
.console-search-toggle:hover { color: #fff; }
.console-status :is(.console-search-toggle, .console-notice-toggle) { position: relative; top: auto; right: auto; width: 44px; height: 44px; padding: 0; flex: none; color: #fff; }
.console-status :is(.console-search-toggle, .console-notice-toggle) svg { width: 24px; height: 24px; }
.console-status :is(button:disabled, button[inert]) { opacity: 0.35; }
.console-application-header { padding-right: calc(var(--status-width) + 12px); }
