import { type ReactNode } from "react";
import { RouteLink } from "@/router/RouterContext";

/** Actions keep native semantics while sharing the console's focus treatment. */
export function XmbRow({ children, value, hint, to, href, onClick, disabled = false }: {
  children: ReactNode;
  value?: ReactNode;
  hint?: string;
  to?: string;
  href?: string;
  onClick?: () => void;
  disabled?: boolean;
}) {
  const body = <><span className="xmb-action-label">{children}</span><span className="xmb-action-value">{value}</span>{(to || href) && <span aria-hidden="true">{href ? "↗" : "›"}</span>}</>;
  const props = { className: "xmb-action-row", "data-info": hint };
  if (to) return <RouteLink {...props} to={to}>{body}</RouteLink>;
  if (href) return <a {...props} href={href} target="_blank" rel="noreferrer noopener">{body}</a>;
  return <button {...props} type="button" disabled={disabled} onClick={onClick}>{body}</button>;
}

/** A single roving focus stop; all four directions select, Enter confirms. */
export function XmbChoice({ label, options, selected, onSelect }: {
  label: string;
  options: readonly { id: string; label: string; hint?: string }[];
  selected: number;
  onSelect: (index: number) => void;
}) {
  return <div className="xmb-choice" role="radiogroup" aria-label={label} onKeyDown={(event) => {
    const delta = ["ArrowRight", "ArrowDown"].includes(event.key) ? 1 : ["ArrowLeft", "ArrowUp"].includes(event.key) ? -1 : 0;
    if (!delta && event.key !== "Home" && event.key !== "End") return;
    event.preventDefault(); event.stopPropagation();
    const next = event.key === "Home" ? 0 : event.key === "End" ? options.length - 1 : (selected + delta + options.length) % options.length;
    onSelect(next);
    event.currentTarget.querySelectorAll<HTMLButtonElement>("button")[next]?.focus();
  }}>
    {options.map((option, index) => <button key={option.id} type="button" role="radio" aria-checked={selected === index}
      tabIndex={selected === index ? 0 : -1} data-info={option.hint ?? option.label}
      onClick={() => onSelect(index)}>{option.label}</button>)}
  </div>;
}

