import { useEffect, useRef, useState, type ReactNode, type RefObject } from "react";
import { XmbList, type XmbListEntry } from "@/xmb/XmbList";
import { blip } from "@/xmb/audio";

export interface XmbScreenEntry extends XmbListEntry {
  description?: string;
  panel?: ReactNode;
  activate?: () => void;
}
export interface XmbScreenSection {
  id: string;
  label: string;
  entries: XmbScreenEntry[];
  panel?: ReactNode;
}

export function XmbPanel({ children }: { children: ReactNode }) {
  return <div className="xmb-text-panel" role="region" tabIndex={0} aria-label="Details">{children}</div>;
}
export function XmbSectionLabel({ children }: { children: ReactNode }) {
  return <h2 className="xmb-section-label">{children}</h2>;
}
export function XmbInfoLine({ children }: { children: ReactNode }) {
  return <p className="xmb-info-line" aria-live="polite" aria-atomic="true">{children}</p>;
}

/** The triangles reflect the real scroll range, including resizes and disclosure. */
export function ScrollEdges({ targetRef }: { targetRef: RefObject<HTMLElement | null> }) {
  const [edges, setEdges] = useState({ up: false, down: false });
  useEffect(() => {
    const el = targetRef.current;
    if (!el) return;
    const update = () => {
      const first = el.matches(".xmb-list--screen") ? el.firstElementChild?.getBoundingClientRect() : null;
      const last = el.matches(".xmb-list--screen") ? el.lastElementChild?.getBoundingClientRect() : null;
      const box = el.getBoundingClientRect();
      const up = first ? first.top < box.top - 2 : el.scrollTop > 2;
      const down = last ? last.bottom > box.bottom + 2 : el.scrollTop + el.clientHeight < el.scrollHeight - 2;
      setEdges((old) => old.up === up && old.down === down ? old : { up, down });
    };
    const resize = new ResizeObserver(update);
    resize.observe(el);
    const mutation = new MutationObserver(() => { update(); for (const child of el.children) resize.observe(child); });
    mutation.observe(el, { childList: true, subtree: true });
    for (const child of el.children) resize.observe(child);
    el.addEventListener("scroll", update, { passive: true });
    update();
    return () => { resize.disconnect(); mutation.disconnect(); el.removeEventListener("scroll", update); };
  }, [targetRef]);
  return <div className="xmb-scroll-indicators" aria-hidden="true"><span data-visible={edges.up}>▲</span><span data-visible={edges.down}>▼</span></div>;
}

/** Shared system screen: a centered row field, one details panel and an info line. */
export function XmbScreen({ subtitle, sections, selected, onSelect, onHighlight, onActivate, initialSelected = 0, initialSection = 0, testId }: {
  subtitle: string;
  sections: XmbScreenSection[];
  selected?: number;
  initialSelected?: number;
  initialSection?: number;
  onSelect?: (index: number) => void;
  onHighlight?: (index: number) => void;
  onActivate?: (index: number) => void;
  testId?: string;
}) {
  const [sectionIndex, setSectionIndex] = useState(initialSection);
  const [localCursor, setLocalCursor] = useState(initialSelected);
  const [highlight, setHighlight] = useState(initialSelected);
  const viewport = useRef<HTMLUListElement>(null);
  const section = sections[Math.min(sectionIndex, sections.length - 1)];
  const entries = section?.entries ?? [];
  const cursor = Math.max(0, Math.min(selected ?? localCursor, entries.length - 1));
  const current = entries[Math.min(highlight, entries.length - 1)] ?? entries[cursor];
  const changeSection = (next: number) => {
    const at = Math.max(0, Math.min(sections.length - 1, next));
    if (at === sectionIndex) return;
    setSectionIndex(at); setLocalCursor(0); setHighlight(0); onSelect?.(0); blip("category");
  };
  const sectionRef = useRef(changeSection);
  sectionRef.current = changeSection;
  useEffect(() => {
    const key = (e: KeyboardEvent) => {
      if (e.defaultPrevented || e.ctrlKey || e.metaKey || e.altKey) return;
      const target = e.target as HTMLElement | null;
      if (target?.closest("[inert], input, textarea, select, [contenteditable=true], [role=dialog]")) return;
      if (!viewport.current?.closest(".console-application:not([inert])")) return;
      if (e.key === "PageUp" || e.key === "PageDown") {
        e.preventDefault(); sectionRef.current(sectionIndex + (e.key === "PageDown" ? 1 : -1));
      } else if ((!target?.closest(".xmb-list, .xmb-text-panel, button, a") || target.closest(".xmb-section-navigation")) && ["ArrowUp", "ArrowDown", "Home", "End", "Enter"].includes(e.key)) {
        e.preventDefault();
        viewport.current?.querySelector<HTMLElement>(".is-selected .xmb-list-link")?.focus({ preventScroll: true });
        viewport.current?.dispatchEvent(new KeyboardEvent("keydown", { key: e.key, bubbles: true, cancelable: true }));
      }
    };
    window.addEventListener("keydown", key);
    return () => window.removeEventListener("keydown", key);
  }, [sectionIndex]);
  if (!section) return null;
  const hasActions = entries.some((entry) => entry.activate || entry.href) || !!onActivate;
  const explanation = current?.description ?? current?.sub ?? current?.value;
  const panel = current?.panel ?? current?.detail ?? section.panel ?? (explanation && explanation.length > 64 ? <p>{explanation}</p> : null);
  return <div className="xmb-screen" data-testid={testId} data-selectable={hasActions}>
    <p className="xmb-screen-subtitle">{subtitle}</p>
    <div className="xmb-section-navigation" role="group" aria-label="Screen sections">
      {sections.map((item, index) => <button key={item.id} type="button" aria-pressed={index === sectionIndex} onClick={() => changeSection(index)}>{item.label}</button>)}
      {sections.length > 1 && <span className="xmb-section-controls">L1 / R1</span>}
    </div>
    <div className="xmb-screen-list-region">
      <XmbList key={section.id} entries={entries} selected={cursor} ariaLabel={section.label} screen viewportRef={viewport} focusOnMount
        onSelect={(index) => { setLocalCursor(index); setHighlight(index); onSelect?.(index); }}
        onHighlight={(index) => { setHighlight(index); onHighlight?.(index); }}
        onActivate={hasActions ? (index) => { entries[index]?.activate?.(); onActivate?.(index); } : undefined} />
      <ScrollEdges key={`${section.id}-edges`} targetRef={viewport} />
    </div>
    <XmbPanel key={current?.key}>{panel ?? <p>{explanation ?? subtitle}</p>}</XmbPanel>
    <XmbInfoLine>{current?.description ?? current?.sub ?? subtitle}</XmbInfoLine>
  </div>;
}

