+name: Prepare first YAG release candidate
+
+on:
+  workflow_dispatch:
+    inputs:
+      tag:
+        description: "New prerelease tag (e.g. v0.1.0-rc.1)"
+        required: true
+        type: string
+
+permissions:
+  contents: write
+  actions: write
+
+concurrency:
+  group: yag-prepare-candidate
+  cancel-in-progress: false
+
+jobs:
+  prepare:
+    name: Verify main and create a new candidate tag
+    if: github.ref == 'refs/heads/main'
+    runs-on: ubuntu-24.04
+    timeout-minutes: 12
+    environment: release-candidate
+    steps:
+      - uses: actions/checkout@v4
+        with:
+          persist-credentials: false
+      - name: Confirm this workflow still points at current main
+        shell: bash
+        env:
+          GH_TOKEN: ${{ github.token }}
+        run: |
+          set -euo pipefail
+          current="$(gh api "repos/$GITHUB_REPOSITORY/git/ref/heads/main" --jq '.object.sha')"
+          if [[ "$current" != "$GITHUB_SHA" ]]; then
+            echo "Main moved; re-run this review on the latest commit." >&2
+            exit 1
+          fi
+      - name: Download exact main-commit CI/security run metadata
+        shell: bash
+        env:
+          GH_TOKEN: ${{ github.token }}
+        run: |
+          set -euo pipefail
+          umask 077
+          gh api "repos/$GITHUB_REPOSITORY/actions/runs?head_sha=$GITHUB_SHA&per_page=100" \
+            > "$RUNNER_TEMP/yag-candidate-runs.json"
+      - name: Fail closed unless newest CI and security reviews passed
+        shell: bash
+        env:
+          RC_TAG: ${{ inputs.tag }}
+        run: |
+          set -euo pipefail
+          python3 scripts/release_candidate.py \
+            --tag "$RC_TAG" --commit "$GITHUB_SHA" \
+            --repository "$GITHUB_REPOSITORY" \
+            --runs-file "$RUNNER_TEMP/yag-candidate-runs.json"
+      - name: Create immutable lightweight prerelease tag
+        shell: bash
+        env:
+          GH_TOKEN: ${{ github.token }}
+          RC_TAG: ${{ inputs.tag }}
+        run: |
+          set -euo pipefail
+          # Never force, replace or re-sign an existing release tag.
+          if gh api "repos/$GITHUB_REPOSITORY/git/ref/tags/$RC_TAG" >/dev/null 2>&1; then
+            echo "Release candidate tag already exists; refusing to overwrite." >&2
+            exit 1
+          fi
+          gh api -X POST "repos/$GITHUB_REPOSITORY/git/refs" \
+            -f ref="refs/tags/$RC_TAG" -f sha="$GITHUB_SHA" >/dev/null
+      - name: Explicitly dispatch the packaged prerelease workflow
+        shell: bash
+        env:
+          GH_TOKEN: ${{ github.token }}
+          RC_TAG: ${{ inputs.tag }}
+        run: |
+          set -euo pipefail
+          # GITHUB_TOKEN tag pushes intentionally do not trigger normal push
+          # workflows. workflow_dispatch is an explicit supported exception.
+          gh workflow run release.yml --repo "$GITHUB_REPOSITORY" --ref "$RC_TAG"
+          {
+            echo "### Release candidate prepared"
+            echo "Tag: \`$RC_TAG\`"
+            echo "Commit: \`$GITHUB_SHA\`"
+            echo "Packaging, checksum and Sigstore attestation run in the release workflow."
+            echo "Only prerelease publication is authorized. No production certification."
+          } >> "$GITHUB_STEP_SUMMARY"
