    the blur never pulls the empty edge of the surface into the picture. */
 .console-environment[data-surface="app"] .console-wallpaper { filter: blur(clamp(16px, 1.9vw, 34px)) saturate(1.04) brightness(1.25); }
 .console-environment[data-surface="app"] .wallpaper-canvas { transform: scale(1.09); }
-.console-menu { position: absolute; inset: 0; z-index: 10; outline: none; transform-origin: 38% 43%; transition: opacity 360ms ease, transform 480ms ease, visibility 0s; }
+/* The menu owns the whole screen, so the fade belongs to it: the rows
+   dissolve toward the footer, while the crossbar and every category stay in
+   the fully opaque top. A zero-height <ul> would clip them instead — the
+   mask must live on a box that really covers the column. */
+.console-menu { position: absolute; inset: 0; z-index: 10; outline: none; transform-origin: 38% 43%; transition: opacity 360ms ease, transform 480ms ease, visibility 0s; -webkit-mask-image: linear-gradient(to bottom, #000 0, #000 78vh, transparent 92vh); mask-image: linear-gradient(to bottom, #000 0, #000 78vh, transparent 92vh); }
 .console-menu[data-hidden="true"] { opacity: 0; visibility: hidden; pointer-events: none; transform: scale(1.13) translateX(-3vw); transition: opacity 280ms, transform 500ms, visibility 0s 400ms; }
 /* Opening: the menu clears away while the selected icon grows and fades; Back plays it in reverse. */
 .console-menu[data-opening="true"] { transform: scale(1.04) translateX(-0.6vw); }
@@ -111,10 +115,11 @@
