          break;
        case "Enter":
        case " ":
          e.preventDefault();
          activate(CATEGORIES[c.cat].items[c.item]);
          break;
        case "Escape":
        case "Backspace":
          e.preventDefault();
          categoryRefs.current[c.cat]?.focus({ preventScroll: true });
          break;
      }
    };
    window.addEventListener("keydown", key);
    return () => window.removeEventListener("keydown", key);
